/* eslint-disable @next/next/no-img-element */
import { useLocale } from "next-intl";

/** Real app screenshots (generated by scripts/screenshots.mjs), in the page's language, switching with the theme. */
export function Shot({ name, alt, className = "", priority = false }: { name: string; alt: string; className?: string; priority?: boolean }) {
  const loading = priority ? "eager" : "lazy";
  const locale = useLocale() === "fr" ? "fr" : "en";
  return (
    <>
      <img src={`/screens/${locale}/light/${name}.png`} alt={alt} className={`block dark:hidden ${className}`} loading={loading} decoding="async" />
      <img src={`/screens/${locale}/dark/${name}.png`} alt={alt} className={`hidden dark:block ${className}`} loading={loading} decoding="async" />
    </>
  );
}

export function BrowserFrame({ children, className = "" }: { children: React.ReactNode; className?: string }) {
  return (
    <div className={`overflow-hidden rounded-xl border border-border bg-surface shadow-[0_24px_60px_-24px_rgba(10,22,38,0.45)] ${className}`}>
      <div className="flex h-7 items-center gap-1.5 border-b border-border px-3">
        <span className="h-2.5 w-2.5 rounded-full bg-border" />
        <span className="h-2.5 w-2.5 rounded-full bg-border" />
        <span className="h-2.5 w-2.5 rounded-full bg-border" />
      </div>
      {children}
    </div>
  );
}

export function LaptopFrame({ children }: { children: React.ReactNode }) {
  return (
    <div className="relative">
      <div className="rounded-t-2xl border-[10px] border-b-0 border-[#1a2a40] bg-[#1a2a40] shadow-[0_30px_80px_-30px_rgba(10,22,38,0.6)]">
        <div className="overflow-hidden rounded-md bg-bg">{children}</div>
      </div>
      <div className="mx-[-6%] h-3.5 rounded-b-2xl bg-gradient-to-b from-[#2a3d57] to-[#16243a]" />
    </div>
  );
}

export function PhoneFrame({ children, className = "" }: { children: React.ReactNode; className?: string }) {
  return (
    <div className={`${className.includes("absolute") ? "" : "relative"} rounded-[2.2rem] border-[7px] border-[#1a2a40] bg-[#1a2a40] shadow-[0_30px_70px_-20px_rgba(10,22,38,0.65)] ${className}`}>
      <div className="absolute left-1/2 top-1.5 z-10 h-4 w-16 -translate-x-1/2 rounded-full bg-[#1a2a40]" />
      <div className="overflow-hidden rounded-[1.7rem] bg-bg">{children}</div>
    </div>
  );
}
